  function esc(s){return String(s===undefined||s===null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function val(s){return esc(s||'');}
  function draft(){return simulation?simulation.data:realDraft;}
  function save(){if(!simulation)writeStore(DRAFT_KEY,JSON.stringify(realDraft));}
  function prettyGrades(g){return (g||[]).map(function(k){return GRADE_LABELS[k]||k;}).join(', ')||'Belum dipilih';}
  function named(s){return String(s||'').trim()||'Belum diketahui — perlu dipastikan sekolah';}
  function hasText(s){return String(s||'').trim().length>0;}
  function promptData(d){
    return {
      'Cakupan lembaga':d.scope==='foundation'?'Beberapa sekolah dalam satu yayasan':'Satu sekolah',
      'Nama lembaga':String(d.name||'').trim()||'Tidak dicantumkan',
      'Jenjang yang dikelola':prettyGrades(d.grades),
      'Jalur atau fokus yang diperhatikan':named(d.focus),
      'Cara memperoleh informasi':d.source==='assessment'?'Ringkasan Peta Kesiapan OSS, ditempel pengguna':'Penjelasan kondisi sekolah oleh pengguna',
      'Ringkasan hasil Peta Kesiapan OSS':d.source==='assessment'?named(d.summary):'Tidak digunakan pada jalur ini',
      'Hal yang sudah berjalan':d.source==='manual'?named(d.strengths):'Ikuti ringkasan hasil pemetaan di atas',
      'Hal yang masih perlu dibenahi':d.source==='manual'?named(d.gaps):'Ikuti ringkasan hasil pemetaan di atas',
      'Prioritas utama': [d.priority1,d.priority2,d.priority3].map(function(x){return String(x||'').trim();}).filter(Boolean),
      'Perubahan yang diharapkan dalam 90 hari':named(d.goal),
      'Pihak yang bisa dilibatkan':named(d.team),
      'Waktu, tenaga, dana atau dukungan yang tersedia':named(d.capacity),
      'Kendala utama':named(d.obstacles)
    };
  }
